const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Point([-74.0060, 40.7128]); // Approximate center of New York City
  const date2024 = '2024-06-24';
  const date2025 = '2025-06-24';

  // Function to get daily max temperature from ERA5-Land hourly data
  const getDailyMaxTemp = (date, geometry) => {
    const start = ee.Date(date);
    const end = start.advance(1, 'day'); // 24 hours for the day

    let collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
      .filterDate(start, end)
      .select('temperature_2m');

    // Check if the collection is empty.
    // We cannot use .getInfo() directly inside a server-side function,
    // so we'll check its size later after the reduce operation.
    const collectionSize = collection.size();

    // If there are images, calculate the daily maximum temperature
    // Convert Kelvin to Celsius: K - 273.15
    const dailyMaxTempC = collection.map(image => image.subtract(273.15))
      .max(); // Get the maximum temperature image for the day

    return {
      dailyMaxTempC: dailyMaxTempC,
      collectionSize: collectionSize
    };
  };

  // 2. Data Acquisition & Check for 2024
  let result2024;
  try {
    const { dailyMaxTempC: maxTemp2024Image, collectionSize: size2024 } = getDailyMaxTemp(date2024, nyc);
    if (size2024.getInfo() === 0) {
      console.log(`No ERA5-Land hourly data found for ${date2024}.`);
      console.log("C1");
      return;
    }

    // 3. Processing and 4. Calculation for 2024
    result2024 = await new Promise((resolve, reject) => {
      maxTemp2024Image.reduceRegion({
        reducer: ee.Reducer.max(), // Use max reducer to get the single point value from the max image
        geometry: nyc,
        scale: 1000, // ERA5-Land resolution is ~9km, 1000m is sufficient
        maxPixels: 1e9
      }).get('temperature_2m').evaluate((val, err) => {
        if (err) reject(err);
        else resolve(val);
      });
    });

    if (result2024 === null || result2024 === undefined) {
      console.log(`Calculation for ${date2024} failed or returned null.`);
      console.log("C3");
      return;
    }
  } catch (e) {
    console.log(`Error processing data for ${date2024}: ${e.message}`);
    console.log("D"); // General error in processing
    return;
  }

  // 2. Data Acquisition & Check for 2025 (Expected to fail)
  let result2025;
  try {
    const { dailyMaxTempC: maxTemp2025Image, collectionSize: size2025 } = getDailyMaxTemp(date2025, nyc);
    if (size2025.getInfo() === 0) {
      console.log(`No ERA5-Land hourly data found for ${date2025}. Earth Engine does not contain future data.`);
      console.log("C1");
      return;
    }

    // 3. Processing and 4. Calculation for 2025
    result2025 = await new Promise((resolve, reject) => {
      maxTemp2025Image.reduceRegion({
        reducer: ee.Reducer.max(),
        geometry: nyc,
        scale: 1000,
        maxPixels: 1e9
      }).get('temperature_2m').evaluate((val, err) => {
        if (err) reject(err);
        else resolve(val);
      });
    });

    if (result2025 === null || result2025 === undefined) {
      console.log(`Calculation for ${date2025} failed or returned null.`);
      console.log("C3");
      return;
    }
  } catch (e) {
    // This catch block is primarily for evaluate errors, not empty collection.
    // The C1 for empty collection is handled above by size2025.getInfo().
    console.log(`Error processing data for ${date2025}: ${e.message}`);
    console.log("D"); // General error in processing
    return;
  }

  // 5. Validation & Final Answer (This part won't be reached due to C1 for 2025)
  console.log(`Max Temp ${date2024}: ${result2024.toFixed(2)} °C`);
  console.log(`Max Temp ${date2025}: ${result2025.toFixed(2)} °C`); // This line should not be reached

  if (result2025 > result2024) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
